#pragma once
// The negotiation bank (v0.30.0; v0.30.1 adds faction questions, the favor bank
// and hostile lines). negotiation_bank.cpp is GENERATED by
// tools/negotiation/make_bank.pl from tools/negotiation/questions.txt,
// faction_questions.txt and favors.txt -- edit those and re-run, never the .cpp.
//
// One SHARED bank: any faction may ask a question, as long as one of its
// replies is one that faction likes. Each reply carries every faction's
// reaction (react[reply][faction]: +1 likes it, 0 neutral, -1 offends), so
// the same words can win one faction over and insult another. After the shared
// questions come each faction's OWN questions (own = that faction), asked only
// once you've revealed the planet's Affiliation.
#include <stdint.h>

#define NEG_EASY 0
#define NEG_MEDIUM 1
#define NEG_HARD 2

struct NegQuestion {
  uint8_t tier;          // NEG_EASY / NEG_MEDIUM / NEG_HARD
  int8_t own;            // -1 = shared; else the faction whose own question this is
  const char *q;         // may contain {planet}
  const char *reply[3];
  int8_t react[3][4];    // [reply][FACTION_*]
};

extern const NegQuestion NEG_BANK[];
extern const int NEG_BANK_COUNT;     // shared questions (sorted by tier); faction ones follow
extern const int NEG_TIER_START[3];
extern const int NEG_TIER_COUNT[3];
extern const int NEG_OWN_START[4];   // NEG_BANK index of each faction's own questions
extern const int NEG_OWN_COUNT[4];

// A favor a faction asks for when a conversation isn't fully convinced.
#define NEG_FAVOR_CREDITS 255   // check: late only -- pay the late price now
struct NegFavor {
  uint8_t faction;
  uint8_t late;          // 1 = the last-rounds bank
  uint8_t hard;          // the one named after two or more misses
  uint8_t check;         // PromiseCheck (game_state.h), or NEG_FAVOR_CREDITS
  int8_t arg;            // faction (TAKE / NO_ATTACK / HOLD_TWO) or Credits per round (TRIBUTE)
  const char *text;      // may contain {planet} and {cr}
};
extern const NegFavor NEG_FAVOR_BANK[];
extern const int NEG_FAVOR_COUNT;

// What a hostile faction says when it unmasks itself (or won't talk at all).
extern const char *const NEG_HOSTILE_LINES[];
extern const int NEG_HOSTILE_START[4];
extern const int NEG_HOSTILE_COUNT[4];
